// V1ProviderCatalogPlan One public plan offering for a provider (GetProvider catalog). Reuses PlanRegion + PlanPrice
// from the same marketplace encoding as ListProviders rows.
type V1ProviderCatalogPlan struct {
	BillingType *V1BillingType `json:"billingType,omitempty"`

	// ComputeCategory - COMPUTE_CATEGORY_SHARED_COMPUTE: Shared compute (shared resources, cost-effective)
	//  - COMPUTE_CATEGORY_DEDICATED_COMPUTE: Dedicated compute (dedicated resources, higher performance)
	ComputeCategory *V1ComputeCategory `json:"computeCategory,omitempty"`

	// ComputeType - COMPUTE_TYPE_GENERAL_COMPUTE: GC - General Compute (balanced performance)
	//  - COMPUTE_TYPE_HIGH_FREQUENCY: HF - High Frequency (CPU-optimized, high clock speeds)
	//  - COMPUTE_TYPE_HIGH_PERFORMANCE: HP - High Performance (next-gen CPUs, NVMe storage)
	//  - COMPUTE_TYPE_GENERAL_PURPOSE: GP - General Purpose (balanced dedicated resources)
	//  - COMPUTE_TYPE_CPU_OPTIMIZED: CPU - CPU Optimized (high CPU-to-memory ratio)
	//  - COMPUTE_TYPE_MEMORY_OPTIMIZED: MEM - Memory Optimized (high memory-to-CPU ratio)
	//  - COMPUTE_TYPE_STORAGE_OPTIMIZED: STO - Storage Optimized (high storage capacity)
	//  - COMPUTE_TYPE_VERY_HIGH_FREQUENCY: VHF - Very High Frequency (highest clock dedicated CPUs)
	//  - COMPUTE_TYPE_GAME_SERVER: GS - Game Server (per-CPU SKU dedicated plans, e.g. DC-GS-9950X-*)
	ComputeType     *V1ComputeType  `json:"computeType,omitempty"`
	PlanCode        *string         `json:"planCode,omitempty"`
	PlanDescription *string         `json:"planDescription,omitempty"`
	PlanId          *string         `json:"planId,omitempty"`
	PlanName        *string         `json:"planName,omitempty"`
	PlanPrices      *[]V1PlanPrice  `json:"planPrices,omitempty"`
	Regions         *[]V1PlanRegion `json:"regions,omitempty"`
}

